seq=''.join(l.strip() for l in open('region.fasta').read().split('\n')[1:] if l.strip())
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}

def best_stem_at(i):
    best=(0,0,0)
    for loop in range(3,25):
        j=i+loop
        L=0
        while i-L-1>=0 and j+L<n and seq[i-L-1]==comp[seq[j+L]]:
            L+=1
        if L>best[0]:
            best=(L,i-L,j+L)
    return best

allhp=[]
for i in range(0,n-1):
    L,a,b=best_stem_at(i)
    if L>=5:
        allhp.append((L,a,b))
# dedupe
seen=set(); out=[]
for L,a,b in sorted(allhp,reverse=True):
    if (a,b) in seen: continue
    seen.add((a,b)); out.append((L,a,b))
print('top hairpins (stemlen, start, end):')
for h in out[:25]:
    print(h, seq[h[1]:h[2]+1] if h[2]-h[1]<80 else '')

# slippery sites
for pos in [160,167,1469,2180]:
